import System.Exception;import System.InvalidOperationException;import System.Globalization.CultureNotFoundException;import java.nio.file.*;import java.util.*;
class OracleTextException extends Exception{String returnMessage,returnStack;int messageReads,stackReads;OracleTextException(String message,String stack,Exception inner){super(null,inner);returnMessage=message;returnStack=stack;}@Override public String get_Message(){messageReads++;return returnMessage;}@Override public String get_StackTrace(){stackReads++;return returnStack;}}
class OracleTextInnerException extends Exception{String text;boolean throwsText;int calls;OracleTextInnerException(String value,boolean throwsValue){text=value;throwsText=throwsValue;}@Override public String ToString(){calls++;if(throwsText)throw new InvalidOperationException("inner text failure");return text;}}
class FoundationExceptionTextFormattingProbe{
 static String text(String csv){if(csv.equals("~"))return null;if(csv.isEmpty())return "";String[] p=csv.split(",");char[] c=new char[p.length];for(int i=0;i<c.length;i++)c[i]=(char)Integer.parseInt(p[i]);return new String(c);}static String units(String s){if(s==null)return "~";StringJoiner out=new StringJoiner(",");for(char c:s.toCharArray())out.add(Integer.toString(c));return out.toString();}static void check(boolean b,String c){if(!b)throw new AssertionError(c);}static Exception inner(int recipe){return switch(recipe){case 0->null;case 1->new Exception("inner");case 2->new Exception((String)null);case 3->new Exception("");case 4->new Exception("middle",new InvalidOperationException(""));case 5->new CultureNotFoundException("param",-1,"culture-inner");default->throw new AssertionError(recipe);};}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);Exception value;OracleTextException control=null;OracleTextInnerException innerControl=null;if(p[0].equals("family")){value=(Exception)Class.forName(p[1]).getConstructor(String.class,Exception.class).newInstance(new Object[]{text(p[2]),inner(Integer.parseInt(p[4]))});}else{Exception cause;if(p[0].equals("innerText")){innerControl=new OracleTextInnerException(text(p[5]),p[6].equals("1"));cause=innerControl;}else cause=inner(Integer.parseInt(p[4]));control=new OracleTextException(text(p[2]),text(p[3]),cause);value=control;}
 try{String result=value.ToString();check(p[7].equals("1")&&units(result).equals(p[8]),"text "+line+" actual="+units(result));}catch(Exception ex){check(p[7].equals("0")&&ex.getClass().getName().equals(p[9])&&units(ex.get_Message()).equals(p[10])&&ex.get_HResult()==Integer.parseInt(p[11]),"failure "+line+" actual="+units(ex.get_Message()));}groups++;
 if(control!=null){check(control.messageReads==Integer.parseInt(p[12]),"message reads "+line);check(control.stackReads==Integer.parseInt(p[13]),"stack reads "+line);groups+=2;}if(innerControl!=null){check(innerControl.calls==Integer.parseInt(p[14]),"inner calls "+line);groups++;}cases++;
 }java.lang.System.out.println("PASS exception text cases="+cases+" groups="+groups);}
}
